import React, { useEffect } from "react";
import popup from "./Popup.module.css";
import Backdrop from "../backdrop/Backdrop";
import { IoIosCloseCircle } from "react-icons/io";

export default function Popup(props: {
    popupTitle: string;
    showPopup: boolean;
    setShowPopup: (val: boolean) => void;
    popupContent: React.JSX.Element;
}) {
    const { popupTitle, showPopup, setShowPopup, popupContent } = props;

    // ✅ LOCK BODY SCROLL
    useEffect(() => {
        if (showPopup) {
            const scrollY = window.scrollY;

            document.body.style.overflow = "hidden";
            document.body.style.position = "fixed";
            document.body.style.top = `-${scrollY}px`;
            document.body.style.width = "100%";

            return () => {
                const storedScrollY = document.body.style.top;

                document.body.style.overflow = "";
                document.body.style.position = "";
                document.body.style.top = "";
                document.body.style.width = "";

                window.scrollTo(0, parseInt(storedScrollY || "0") * -1);
            };
        }
    }, [showPopup]);

    return (
        <>
            {showPopup && <Backdrop close={() => setShowPopup(false)} />}
            <div
                className={popup.modalmobile}
                id={showPopup ? undefined : popup.hide}
            >
                <div className={popup.header}>
                    <div
                        className={popup.closeButton}
                        onClick={() => setShowPopup(false)}
                    >
                        <IoIosCloseCircle />
                    </div>

                    {popupTitle != null ? (
                        <h2 style={{ textAlign: "center", margin: "0" }}>
                            {popupTitle.toUpperCase().replace("_", " ")}
                        </h2>
                    ) : null}
                </div>

                <div className={popup.content}>{popupContent}</div>
            </div>
        </>
    );
}